/bin/bash -lc "python - <<'PY'
import urllib.request, urllib.error, os
for u in ['https://api.assemblyai.com/v2/transcript','https://assemblyai.com/docs/audio-intelligence/pii-redaction','https://www.assemblyai.com/docs/api-reference/transcripts/submit','https://pypi.org/pypi/assemblyai/json']:
 try:
  req=urllib.request.Request(u,headers={'authorization':os.environ['ASSEMBLYAI_API_KEY']} if 'api.assemblyai.com/' in u else {})
  with urllib.request.urlopen(req,timeout=15) as r:
   b=r.read(); print(u,r.status,len(b));
   if 'pypi' in u: open('/tmp/assembly-pypi.json','wb').write(b)
 except Exception as e: print(u,type(e).__name__,str(e))
PY"

